import{_ as r,C as l,o as t,c as d,a2 as a,b as i,w as o,a as s,E as c,a3 as h}from"./chunks/framework.DToEn73J.js";const _=JSON.parse('{"title":"模型路由：按复杂度调度模型","description":"","frontmatter":{"title":"模型路由：按复杂度调度模型","chapter":"4.4","order":4,"summary":"按任务复杂度把请求路由到不同规模模型，在成本/延迟/质量三角中权衡，并设计 fallback 链保障可用性。"},"headers":[],"relativePath":"04-planning-execution/model-routing.md","filePath":"04-planning-execution/model-routing.md","lastUpdated":1788254264000}'),E={name:"04-planning-execution/model-routing.md"};function p(g,e,u,A,m,B){const n=l("Mermaid");return t(),d("div",null,[e[1]||(e[1]=a('<h1 id="模型路由-按复杂度调度模型" tabindex="-1">模型路由：按复杂度调度模型 <a class="header-anchor" href="#模型路由-按复杂度调度模型" aria-label="Permalink to &quot;模型路由：按复杂度调度模型&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>模型路由（Model Routing）是根据任务难度、预算与延迟 SLA，把请求动态派发到合适型号（小模型/大模型/专用模型）的调度层，是 Cost-Latency 优化的核心手段。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><p><strong>路由决策信号</strong>：任务分类（分类/抽取/生成/推理）、输入长度、用户指定 SLA、历史成本。简单任务走低成本的轻量模型，复杂推理才上旗舰模型。</p><p><strong>成本 / 延迟 / 质量三角权衡</strong>：</p><table tabindex="0"><thead><tr><th>模型档位</th><th>单位成本</th><th>延迟</th><th>质量（难题）</th><th>适用</th></tr></thead><tbody><tr><td>轻量模型</td><td>低</td><td>低</td><td>弱</td><td>分类、抽取、格式化</td></tr><tr><td>中档模型</td><td>中</td><td>中</td><td>中</td><td>常规生成、RAG 归纳</td></tr><tr><td>旗舰模型</td><td>高</td><td>高</td><td>强</td><td>多步推理、规划、代码</td></tr></tbody></table><p><strong>Fallback 链</strong>：主模型超时/限流/返回非法时，按 <code>旗舰 → 中档 → 轻量</code> 或跨供应商降级，保证可用性。</p>',8)),(t(),i(h,null,{default:o(()=>[c(n,{id:"mermaid-95",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E4%BB%BB%E5%8A%A1%5D%20--%3E%20R%7B%E8%B7%AF%E7%94%B1%E5%88%86%E7%B1%BB%7D%0A%20%20%20%20R%20--%3E%7C%E7%AE%80%E5%8D%95%7C%20M1%5B%E8%BD%BB%E9%87%8F%E6%A8%A1%E5%9E%8B%5D%0A%20%20%20%20R%20--%3E%7C%E4%B8%AD%E7%AD%89%7C%20M2%5B%E4%B8%AD%E6%A1%A3%E6%A8%A1%E5%9E%8B%5D%0A%20%20%20%20R%20--%3E%7C%E5%9B%B0%E9%9A%BE%7C%20M3%5B%E6%97%97%E8%88%B0%E6%A8%A1%E5%9E%8B%5D%0A%20%20%20%20M1%20--%3E%20C%7B%E6%88%90%E5%8A%9F%3F%7D%0A%20%20%20%20M2%20--%3E%20C%0A%20%20%20%20M3%20--%3E%20C%0A%20%20%20%20C%20--%3E%7C%E5%90%A6%7C%20F%5B%E4%B8%8B%E4%B8%80%E6%A1%A3%20fallback%5D%0A%20%20%20%20F%20--%3E%20C%0A%20%20%20%20C%20--%3E%7C%E6%98%AF%7C%20O%5B%E8%BE%93%E5%87%BA%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<p>最小实现：<code>route(task) -&gt; model_id</code>，调用封装 <code>with_fallback([m3, m2, m1])</code>；路由策略可离线由 SWE-bench 类评测标定。</p><h2 id="为什么" tabindex="-1">为什么 <a class="header-anchor" href="#为什么" aria-label="Permalink to &quot;为什么&quot;">​</a></h2><p>全量使用旗舰模型在高频简单请求上浪费显著成本与延迟；全量用小模型则在难题上质量塌方。路由把预算花在刀刃上。但路由判错（低估难度）会导致质量事故，故 fallback 链必须兜底。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>路由只看成本不看质量，简单阈值把推理题误判给小模型，产出不可用结果。</li><li>Fallback 链未跨供应商，主供应商宕机时整条链同时失效。</li></ul><h2 id="业界实现对照" tabindex="-1">业界实现对照 <a class="header-anchor" href="#业界实现对照" aria-label="Permalink to &quot;业界实现对照&quot;">​</a></h2><ul><li><strong>OpenAI Agents SDK</strong>：<code>Model</code> 可指定并动态切换（<a href="https://openai.github.io/openai-agents-python/%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://openai.github.io/openai-agents-python/）。</a></li><li><strong>LangChain</strong>：<code>RouterChain</code> 做任务分流（<a href="https://python.langchain.com/docs/modules/model_io/%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://python.langchain.com/docs/modules/model_io/）。</a></li><li><strong>Claude Agent SDK</strong>：<code>model</code> 参数支持运行时选择（<a href="https://docs.anthropic.com/en/docs/claude-agent-sdk%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://docs.anthropic.com/en/docs/claude-agent-sdk）。</a></li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/fk-ai-agent/04-planning-execution/plan-and-execute">/04-planning-execution/plan-and-execute</a></li><li><a href="/fk-ai-agent/06-engineering-ops/cost-latency">/06-engineering-ops/cost-latency</a></li><li><a href="/fk-ai-agent/01-agent-basics/budget-control">/01-agent-basics/budget-control</a></li><li><a href="/fk-ai-agent/06-engineering-ops/evaluation-swebench">/06-engineering-ops/evaluation-swebench</a></li></ul><hr><p><em>最后核实日期：2026-08-26</em></p>',11))])}const f=r(E,[["render",p]]);export{_ as __pageData,f as default};
